  p_dbDeep = texelFetch(lookSettings, ivec2(2, 0), 0).rgb;
  p_dbSilverC = texelFetch(lookSettings, ivec2(3, 0), 0).rgb;
  p_dbScale = texelFetch(lookSettings, ivec2(4, 0), 0).r;
