  p_dbTwist = texelFetch(lookSettings, ivec2(6, 0), 0).r;
  p_dbStrip = texelFetch(lookSettings, ivec2(7, 0), 0).r;
  p_dbFurrow = texelFetch(lookSettings, ivec2(8, 0), 0).r;
  p_dbPlates = texelFetch(lookSettings, ivec2(9, 0), 0).r;
  p_dbSilver = texelFetch(lookSettings, ivec2(10, 0), 0).r;
  p_dbRelief = texelFetch(lookSettings, ivec2(11, 0), 0).r;

    vS0 = (modelMatrix * vec4(s0.x, s0.z, -s0.y, 0.0)).xyz;

}

void lookVertex_1() {
  p_dbBark = texelFetch(lookSettings, ivec2(0, 1), 0).rgb;
  p_dbUnder = texelFetch(lookSettings, ivec2(1, 1), 0).rgb;
  p_dbDeep = texelFetch(lookSettings, ivec2(2, 1), 0).rgb;
  p_dbSilverC = texelFetch(lookSettings, ivec2(3, 1), 0).rgb;
  p_dbScale = texelFetch(lookSettings, ivec2(4, 1), 0).r;
  p_dbStretch = texelFetch(lookSettings, ivec2(5, 1), 0).r;
  p_dbTwist = texelFetch(lookSettings, ivec2(6, 1), 0).r;
  p_dbStrip = texelFetch(lookSettings, ivec2(7, 1), 0).r;
  p_dbFurrow = texelFetch(lookSettings, ivec2(8, 1), 0).r;
  p_dbPlates = texelFetch(lookSettings, ivec2(9, 1), 0).r;
  p_dbSilver = texelFetch(lookSettings, ivec2(10, 1), 0).r;
  p_dbRelief = texelFetch(lookSettings, ivec2(11, 1), 0).r;

