vertexMain:
vLookId = lookId;
vLookInfo = lookInfo;
vLookUv = uv;
vLookWorld = (modelMatrix * vec4(position, 1.0)).xyz;
vLookWN = normalize(mat3(modelMatrix) * normal);
vS0 = s0;
vS1 = s1;
vS2 = s2;
vS3 = s3;
switch (int(lookId + 0.5)) {
  case 0: lookVertex_0(); break;
  case 1: lookVertex_1(); break;
}

