    // the bark on one upright plane: p.x across, p.y up. Returns (colour mix toward the under-bark, deep, silver
    // grain), the relief in .w
    vec4 dbUp(vec2 p, float scale, float stretch, float twist, float strip, float furrow, float plates, float silver) {
      // the twist: the features lean across as they go up, twist metres across for every metre up
      p.x += p.y * twist;
      vec2 q = vec2(p.x * scale, p.y * scale / stretch);
      float n = kfbm(q + vec2(0.0, kn(q * 0.3) * 2.0));
      // strips: long fibres, each its own tone, their edges lifting; the red under-bark where one has peeled
      float fib = kn(vec2(q.x * 3.0, q.y * 0.6));
      float peel = smoothstep(0.66, 0.82, kfbm(q * vec2(0.6, 0.2) + 5.0)) * strip;
      // a strip's edge: a ragged dark seam where one strip lifts off the next, each seam its own course
      float seamAt = fract(q.x + 0.9 * n + 0.4 * kn(vec2(q.x * 0.5, q.y * 0.15)));
      float stripEdge = (1.0 - smoothstep(0.0, 0.06, abs(seamAt - 0.5))) * smoothstep(0.35, 0.6, kn(q * vec2(1.0, 0.3) + 2.0)) * strip;
      // furrows: deep valleys between ridges, the ridges flat-topped and broken across
      float ridge = smoothstep(0.15, 0.45, abs(fract(q.x * 0.5 + 0.6 * n) - 0.5) * 2.0);
      float ridgeBreak = smoothstep(0.0, 0.08, abs(fract(q.y * 0.3 + n) - 0.5) - 0.42);
      float furrowDeep = (1.0 - ridge * (1.0 - ridgeBreak * 0.5)) * furrow;
      // plates: cells stretched up, dark between them, orange where one has flaked
      float pid, pe;
      // q is already stretched up the trunk by the stretch setting: the plates come out long that way
      kvor(q + vec2(0.3 * kn(q * 2.0), 0.0), pid, pe);
      float plateGap = (1.0 - smoothstep(0.01, 0.06, pe)) * plates;
      float flake = step(0.9, pid) * smoothstep(0.03, 0.12, pe) * plates;
      // the silvered wood: its grain lines, cracks along it
      float grain = kn(vec2(q.x * 6.0, q.y * 0.4));
      float crack = (1.0 - smoothstep(0.0, 0.03, abs(kfbm(vec2(q.x * 1.3, q.y * 0.15) + 9.0) - 0.5))) * silver;
      float under = clamp(peel + flake, 0.0, 1.0);
      float deep = clamp(stripEdge * 0.6 + furrowDeep + plateGap + crack, 0.0, 1.0);
      float relief = (fib - 0.5) * 0.3 * strip + ridge * furrow - plateGap * 0.5 - crack * 0.6 + (grain - 0.5) * 0.2 * silver;
      // its tone: the fibres of a strip each their own, the grain of silvered wood
      float tone = mix(mix(0.5, fib, strip), grain, silver);
      return vec4(under, deep, tone, relief);
    }


    // one layer of leaf elements at p (cells of 1): how much of an element covers it (0 to 1), its number, and where
    // along it (0 its stalk, 1 its tip)
    float dfLayer(vec2 p, float size, float len, out float id, out float along) {
      vec2 i = floor(p), f = fract(p);
      float best = 0.0;
      id = 0.0; along = 0.5;
      for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) {
        vec2 o = vec2(x, y);
        vec2 c = i + o;
        float h = kh(c + 1.3);
        vec2 r = f - o - vec2(kh(c), kh(c + 7.3));
        float a = h * 6.2832;
        vec2 ax = vec2(cos(a), sin(a));
        float u = dot(r, ax), v = dot(r, vec2(-ax.y, ax.x));
        float l = size * (0.8 + 0.45 * kh(c + 2.9));
        float d = length(vec2(u / l, v * len / l));
        float cov = 1.0 - smoothstep(0.8, 1.0, d);
        if (cov > best) { best = cov; id = h; along = clamp(u / l * 0.5 + 0.5, 0.0, 1.0); }
      }
      return best;
    }
    // the two layers and the tufts on one plane: (top layer, under layer, tuft crown) and the top layer's id and along
    vec3 dfPlane(vec2 p, float leaves, float cover, float len, float tufts, out float id0, out float al0, out float id1) {
      float al1;
      float l0 = dfLayer(p * leaves, cover, len, id0, al0);
      float l1 = dfLayer(p * leaves * 1.17 + 17.0, cover, len, id1, al1);
      float sid, se;
      float sd = kvor(p * tufts + vec2(kn(p * 12.0), kn(p * 12.0 + 3.0)) * 0.35, sid, se);
      float rag = (kfbm4(p * tufts * 3.0 + 11.0) - 0.5) * 0.35;
      float crown = smoothstep(0.85, 0.3, sd + rag) * (0.85 + 0.3 * kh1(sid * 23.0));
      return vec3(l0, l1, crown);
    }

void look_0(inout Look k, int lookRow) {
