  p_dbFurrow = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_dbPlates = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_dbSilver = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
