  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the frame the features are laid in: along the limb's way where the kind gave it, else up the world
    vec3 dbAx = length(s0) > 0.5 ? normalize(s0) : vec3(0.0, 1.0, 0.0);
    vec3 dbRef = abs(dbAx.y) < 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);
    vec3 dbE1 = normalize(cross(dbAx, dbRef));
    vec3 dbE2 = cross(dbAx, dbE1);
    vec3 dbW = pow(abs(vec3(dot(wn, dbE1), dot(wn, dbAx), dot(wn, dbE2))), vec3(4.0));
    dbW /= dbW.x + dbW.y + dbW.z;
    vec2 dbO = vec2(seed * 3.7, seed * 1.3);
    float dbAlong = dot(wp, dbAx);
    // facing e1: laid on the plane of e2 and the way; facing e2: on the plane of e1 and the way
    vec4 dbX = dbUp(vec2(dot(wp, dbE2), dbAlong) + dbO, p_dbScale, p_dbStretch, p_dbTwist, p_dbStrip, p_dbFurrow, p_dbPlates, p_dbSilver);
    vec4 dbZ = dbUp(vec2(dot(wp, dbE1), dbAlong) + dbO.yx, p_dbScale, p_dbStretch, p_dbTwist, p_dbStrip, p_dbFurrow, p_dbPlates, p_dbSilver);
    // facing along the way: a cut end or a level top, its rings
    float dbRing = kring(vec2(dot(wp, dbE1), dot(wp, dbE2)) * 2.0, seed, 14.0);
    vec4 dbY = vec4(0.0, 0.2 * smoothstep(0.6, 0.9, dbRing), dbRing, (dbRing - 0.5) * 0.3);
    float dbSide = dbW.x + dbW.z;
    vec4 dbV = (dbX * dbW.x + dbZ * dbW.z) + dbY * dbW.y;
