    k.ao = mix(0.75, mix(0.35, 1.0, dfDepthAt), dfF) * mix(0.5, 1.0, dfCrown);
    k.aoDirect = 0.6;
    k.sheen = mix(p_dfTip * 0.35, vec3(0.5), p_dfFelt * 0.6);
    k.sheenRough = 0.5;
    if (lookView > 0.5 && lookView < 1.5) k.colour = vec3(dfL0, dfB, dfCrown);

}

void look_3(inout Look k, int lookRow) {
  p_lcCut = texelFetch(lookSettings, ivec2(0, lookRow), 0).r;
  p_lcRough = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  t_lcPic = 0;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec4 lcD = picDataS3(t_lcPic, s3);
    // the picture's colour is stored times its alpha: divided out, then made linear
    vec3 lcC = clamp(lcD.rgb / max(lcD.a, 0.02), 0.0, 1.0);
    lcC = mix(lcC / 12.92, pow((lcC + 0.055) / 1.055, vec3(2.4)), step(0.04045, lcC));
    k.colour = lcC;
    k.alpha = lcD.a >= p_lcCut ? 1.0 : 0.0;
    k.rough = p_lcRough;
    k.metal = 0.0;

}





Look lookRun(int id) {
  Look k = lookStart();
  switch (id) {
    case 0: look_0(k, 0); break;
    case 1: look_0(k, 1); break;
    case 2: look_2(k, 2); break;
    case 3: look_3(k, 3); break;
  }
  if (lookDebug > 0.5) {
    switch (id) {
